presets.css:
/* Puff · 乙女游戏 · 桌面完整主题（深色方机 · 闪现渐隐台词版）
   蓝调渐变 · 像素蝴蝶结/水晶 · 轻盈气泡 · 方形手柄 + 荧光台词 */

/* ========== A. 变量 ========== */
.device {
  --ot-mist:      #EEF5FE;
  --ot-ice:       #D4E6FA;
  --ot-sky:       #B8D4EE;
  --ot-corn:      #8FB4E0;
  --ot-azure:     #5B8DD9;
  --ot-royal:     #3A5FA8;
  --ot-night:     #233A6B;

  --ot-pearl:     #F8FBFF;
  --ot-glow:      #A8D0FF;
  --ot-crystal:   #C8DCF5;
  --ot-gold:      #E8C87A;
  --ot-gold-hi:   #F5E2A8;
  --ot-gold-deep: #C9A854;
  --ot-gold-line: rgba(232, 200, 122, 0.42);

  --ot-line:      rgba(91, 141, 217, 0.30);
  --ot-line-soft: rgba(91, 141, 217, 0.16);

  --bb-hi:      rgba(255, 255, 255, 0.95);
  --bb-mid:     rgba(222, 240, 255, 0.42);
  --bb-rim:     rgba(150, 200, 250, 0.65);
  --bb-shade:   rgba(110, 165, 225, 0.38);

  --ot-dlg-glow:   rgba(120, 190, 255, 1);
  --ot-dlg-glow-2: rgba(120, 190, 255, 0.85);
  --ot-dlg-glow-3: rgba(120, 190, 255, 0.6);
  --ot-dlg-glow-4: rgba(91, 141, 217, 0.45);

  --dress-desk-glass:        rgba(238, 245, 254, 0.48);
  --dress-desk-glass-strong: rgba(248, 251, 255, 0.72);
  --dress-desk-glass-border: rgba(168, 208, 255, 0.55);
  --dress-app-ico-radius: 6px;
  --dress-app-label-size: 10px;
  --dress-app-label-tracking: 0.08em;
  --dress-wg-radius: 6px;

  --glass: var(--dress-desk-glass);
  --glass-strong: var(--dress-desk-glass-strong);
  --glass-border: var(--dress-desk-glass-border);

  --ot-font: "PingFang SC", "Noto Sans SC", "HarmonyOS Sans SC",
             system-ui, sans-serif;

  --stu-grid-gap-x: 22px;
  --stu-grid-gap-y: 26px;
  --stu-ico-scale: 0.88;

  --stu-wg-pad: 12px;
  --stu-wg-gap: 14px;
  --stu-wg-radius: 6px;
  --stu-wg-head-h: 132px;
  --stu-avatar-size: 42px;
  --stu-wg-row-gap: 14px;

  --stu-dock-pad: 10px;
  --stu-dock-gap: 14px;
  --stu-dock-ico: 46px;

  --px: 4px;
}

html[data-theme="dark"] .device {
  --ot-mist:      #1A2E54;
  --ot-ice:       #14264A;
  --ot-sky:       #1E3660;
  --ot-corn:      #243E6E;
  --ot-azure:     #3A5A8E;
  --ot-royal:     #2A4880;
  --ot-night:     #0D1830;

  --ot-crystal:   rgba(168, 208, 255, 0.45);
  --ot-line:      rgba(168, 208, 255, 0.22);
  --ot-line-soft: rgba(168, 208, 255, 0.10);

  --bb-hi:      rgba(230, 244, 255, 0.85);
  --bb-mid:     rgba(150, 195, 245, 0.40);
  --bb-rim:     rgba(110, 165, 225, 0.60);
  --bb-shade:   rgba(80, 130, 195, 0.42);

  --dress-desk-glass:        rgba(13, 24, 48, 0.52);
  --dress-desk-glass-strong: rgba(22, 38, 74, 0.74);
  --dress-desk-glass-border: rgba(168, 208, 255, 0.28);
}

/* ========== A2. 全局兜底 ========== */
html, body {
  width: 100%;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}

/* ========== B. 设备壳 / 画布 / 状态栏 ========== */
.desk {
  width: 100%;
  min-width: 100%;
  background-color: var(--ot-mist);
  background-image:
    radial-gradient(120% 30% at 50% -6%,
      rgba(248, 251, 255, 0.9) 0%,
      transparent 62%),
    radial-gradient(60% 30% at 92% 8%,
      rgba(168, 208, 255, 0.45) 0%,
      transparent 70%),
    radial-gradient(70% 40% at -8% 96%,
      rgba(242, 200, 208, 0.28) 0%,
      transparent 68%),
    linear-gradient(180deg,
      var(--ot-mist) 0%,
      var(--ot-ice) 20%,
      var(--ot-sky) 45%,
      var(--ot-corn) 68%,
      var(--ot-azure) 88%,
      var(--ot-royal) 100%);
  color: var(--ot-night);
  font-family: var(--ot-font);
}

html[data-theme="dark"] .desk {
  background-image:
    radial-gradient(120% 30% at 50% -6%,
      rgba(91, 141, 217, 0.45) 0%,
      transparent 62%),
    radial-gradient(60% 30% at 92% 8%,
      rgba(168, 208, 255, 0.22) 0%,
      transparent 70%),
    linear-gradient(180deg,
      var(--ot-mist) 0%,
      var(--ot-ice) 20%,
      var(--ot-sky) 45%,
      var(--ot-night) 78%,
      #0A1228 100%);
}

.desk::before,
.desk::after {
  content: none !important;
  display: none !important;
  background: none !important;
  box-shadow: none !important;
  animation: none !important;
}

.status {
  color: var(--ot-royal);
  font-family: var(--ot-font);
  font-size: 0.84em;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-shadow: 0 1px 6px rgba(168, 208, 255, 0.7);
}
html[data-theme="dark"] .status {
  color: var(--ot-glow);
  text-shadow: 0 0 10px rgba(168, 208, 255, 0.45);
}

/* ========== C. 应用图标 ========== */
.tile.app {
  padding: 4px;
  min-height: 0;
  overflow: hidden;
}

.app-box {
  padding: 2px 0;
}

.app-box .ico {
  border-radius: var(--dress-app-ico-radius);
  border: 1px solid var(--ot-line);
  background: linear-gradient(
    155deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(220, 236, 255, 0.48) 45%,
    rgba(168, 208, 255, 0.35) 100%
  );
  transform: scale(var(--stu-ico-scale));
  transform-origin: center bottom;
  box-shadow:
    var(--px) var(--px) 0 0 rgba(91, 141, 217, 0.18),
    0 0 14px rgba(168, 208, 255, 0.45),
    inset 0 0 0 1px rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(10px) saturate(1.2);
  -webkit-backdrop-filter: blur(10px) saturate(1.2);
  transition: transform 0.1s steps(2, end), box-shadow 0.1s steps(2, end);
}
.app-box:active .ico {
  transform: scale(var(--stu-ico-scale)) translate(2px, 2px);
  box-shadow:
    1px 1px 0 0 rgba(91, 141, 217, 0.15),
    0 0 8px rgba(168, 208, 255, 0.4);
}

.app-box span {
  font-size: var(--dress-app-label-size);
  letter-spacing: var(--dress-app-label-tracking);
  font-family: var(--ot-font);
  font-weight: 400;
  color: var(--ot-night);
  margin-top: 4px;
  text-shadow: 0 1px 3px rgba(255, 255, 255, 0.8);
}
html[data-theme="dark"] .app-box span {
  color: var(--ot-pearl);
  text-shadow: none;
}

.tile.app[data-d="1"] .ico {
  box-shadow:
    6px 6px 0 0 rgba(91, 141, 217, 0.2),
    0 0 20px rgba(168, 208, 255, 0.5),
    inset 0 0 0 1px rgba(255, 255, 255, 0.65);
}

/* ========== D. 小组件壳 ========== */
.wg-profile,
.wg-hero,
.wg-note,
.wg-quote,
.wg-custom {
  border-radius: var(--stu-wg-radius);
  background: linear-gradient(
    155deg,
    rgba(248, 251, 255, 0.62) 0%,
    rgba(220, 236, 255, 0.42) 50%,
    rgba(168, 208, 255, 0.30) 100%
  );
  border: 1px solid var(--ot-line);
  color: var(--ot-night);
  font-family: var(--ot-font);
  box-shadow:
    var(--px) var(--px) 0 0 rgba(91, 141, 217, 0.16),
    0 0 18px rgba(168, 208, 255, 0.35),
    inset 0 0 0 1px rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(18px) saturate(1.3);
  -webkit-backdrop-filter: blur(18px) saturate(1.3);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  min-height: 0;
  padding: var(--stu-wg-pad);
}

.wg-profile,
.wg-hero {
  height: var(--stu-wg-head-h);
  max-height: var(--stu-wg-head-h);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  overflow: visible;
}

.wg-profile img,
.wg-hero img,
.wg-profile .avatar,
.wg-hero .avatar,
.wg-profile [class*="avatar"],
.wg-hero [class*="avatar"],
.wg-profile [class*="face"],
.wg-hero [class*="face"] {
  width: var(--stu-avatar-size);
  height: var(--stu-avatar-size);
  min-width: var(--stu-avatar-size);
  min-height: var(--stu-avatar-size);
  max-width: var(--stu-avatar-size);
  max-height: var(--stu-avatar-size);
  border-radius: 4px;
  object-fit: cover;
  display: block;
  flex-shrink: 0;
  align-self: center;
  overflow: hidden;
  border: 2px solid var(--ot-gold);
  box-shadow:
    0 0 0 2px rgba(248, 251, 255, 0.8),
    0 0 18px rgba(168, 208, 255, 0.6),
    3px 3px 0 0 rgba(91, 141, 217, 0.2);
  image-rendering: pixelated;
}

.wg-profile > *,
.wg-hero > *,
.wg-note > *,
.wg-quote > *,
.wg-custom > * {
  max-width: 100%;
}

.wg-profile {
  background: linear-gradient(
    155deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(220, 236, 255, 0.48) 100%
  );
}

.wg-hero {
  background-image:
    linear-gradient(rgba(91, 141, 217, 0.10) 1px, transparent 1px),
    linear-gradient(90deg, rgba(91, 141, 217, 0.10) 1px, transparent 1px),
    linear-gradient(155deg,
      rgba(248, 251, 255, 0.62) 0%,
      rgba(220, 236, 255, 0.42) 50%,
      rgba(168, 208, 255, 0.30) 100%);
  background-size: 12px 12px, 12px 12px, 100% 100%;
}

.wg-note {
  background-color: rgba(248, 251, 255, 0.58);
  background-image:
    radial-gradient(circle, rgba(91, 141, 217, 0.18) 1.6px, transparent 2px);
  background-size: 12px 12px;
  border-color: var(--ot-line);
  color: var(--ot-royal);
  padding: 9px 10px 12px;
  font-size: 0.88em;
  line-height: 1.42;
  overflow: hidden;
}
.wg-note *,
.wg-note p,
.wg-note span,
.wg-note div {
  white-space: normal !important;
  word-break: break-word;
  overflow-wrap: anywhere;
  text-overflow: clip;
  overflow: visible;
  max-width: 100%;
  line-height: 1.42;
}
.wg-note::after {
  content: "";
  position: absolute;
  right: 10px;
  bottom: 10px;
  width: 3px;
  height: 3px;
  background: var(--ot-gold);
  border-radius: 0;
  box-shadow:
    -6px -3px 0 0 var(--ot-azure),
    -3px -3px 0 0 var(--ot-azure),
    -6px 0 0 0 var(--ot-azure),
    -3px 0 0 0 var(--ot-azure),
     3px -3px 0 0 var(--ot-azure),
     6px -3px 0 0 var(--ot-azure),
     3px 0 0 0 var(--ot-azure),
     6px 0 0 0 var(--ot-azure),
     0 3px 0 0 var(--ot-gold-hi),
     0 6px 0 0 var(--ot-gold-hi);
  filter: drop-shadow(0 0 4px rgba(232, 200, 122, 0.6));
  pointer-events: none;
}

.wg-quote {
  background: linear-gradient(
    155deg,
    rgba(248, 251, 255, 0.62) 0%,
    rgba(220, 236, 255, 0.42) 50%,
    rgba(168, 208, 255, 0.30) 100%
  );
}
.wg-quote::before {
  content: "";
  position: absolute;
  left: 14px;
  top: 14px;
  width: 3px;
  height: 3px;
  background: var(--ot-pearl);
  border-radius: 0;
  box-shadow:
    0 -6px 0 0 var(--ot-crystal),
    -3px -3px 0 0 var(--ot-crystal),
    0 -3px 0 0 var(--ot-pearl),
    3px -3px 0 0 var(--ot-crystal),
    -3px 0 0 0 var(--ot-crystal),
    3px 0 0 0 var(--ot-crystal),
    -3px 3px 0 0 var(--ot-azure),
    0 3px 0 0 var(--ot-azure),
    3px 3px 0 0 var(--ot-azure),
    0 6px 0 0 var(--ot-royal);
  filter: drop-shadow(0 0 5px rgba(168, 208, 255, 0.8));
  pointer-events: none;
}

/* ========== 方形游戏机组件（在一起多少天） ========== */
.wg-cd {
  position: relative;
  overflow: visible;
  box-sizing: border-box;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;

  padding: 26px 20px 34px;
  margin-bottom: var(--stu-wg-row-gap);

  /* 方形外壳 */
  border-radius: 8px;

  background-image:
    /* —— 底部按钮：D-pad 横条 —— */
    linear-gradient(0deg, #6A8CC0 0 100%),
    /* —— 底部按钮：D-pad 竖条 —— */
    linear-gradient(0deg, #6A8CC0 0 100%),
    /* —— 底部按钮：A 键 —— */
    radial-gradient(circle at 50% 50%, #E8BCC8 0 42%, #C890A5 43% 100%),
    /* —— 底部按钮：B 键 —— */
    radial-gradient(circle at 50% 50%, #E8BCC8 0 42%, #C890A5 43% 100%),
    /* —— 外壳像素网格 —— */
    repeating-linear-gradient(0deg,
      rgba(255, 255, 255, 0.07) 0 1px,
      transparent 1px 4px),
    repeating-linear-gradient(90deg,
      rgba(255, 255, 255, 0.07) 0 1px,
      transparent 1px 4px),
    /* —— 外壳主渐变：整体压深一档 —— */
    linear-gradient(180deg,
      #7FA8DE 0%,
      #4A7AC0 25%,
      #2E5599 62%,
      #1B3568 100%);
  background-size:
    20px 6px,
    6px 20px,
    12px 12px,
    12px 12px,
    4px 4px,
    4px 4px,
    100% 100%;
  background-position:
    left 18% bottom 11px,
    left 26% bottom 4px,
    right 30% bottom 8px,
    right 14% bottom 8px,
    center center,
    center center,
    center center;
  background-repeat: no-repeat;

  border: 2px solid rgba(232, 200, 122, 0.62);

  box-shadow:
    4px 6px 0 0 rgba(20, 40, 80, 0.55),
    0 0 24px rgba(91, 141, 217, 0.55),
    inset 0 2px 0 rgba(255, 255, 255, 0.4),
    inset 0 -3px 0 rgba(20, 40, 80, 0.4),
    inset 0 0 0 1px rgba(232, 200, 122, 0.2);

  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

/* 荧光屏 */
.wg-cd::before {
  content: "";
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: calc(100% - 36px);
  height: 44%;
  border-radius: 4px;
  pointer-events: none;
  z-index: 0;

  background-image:
    repeating-linear-gradient(0deg,
      rgba(168, 208, 255, 0.10) 0 1px,
      transparent 1px 3px),
    radial-gradient(120% 60% at 50% 0%,
      rgba(220, 236, 255, 0.35) 0%,
      transparent 60%),
    linear-gradient(180deg,
      #14224A 0%,
      #1C3266 50%,
      #14224A 100%);
  border: 1px solid rgba(232, 200, 122, 0.5);

  box-shadow:
    inset 0 0 16px rgba(168, 208, 255, 0.5),
    inset 0 2px 4px rgba(0, 0, 0, 0.6),
    inset 0 0 0 1px rgba(168, 208, 255, 0.25),
    0 1px 0 rgba(255, 255, 255, 0.12);
}

/* 数字区 */
.wg-cd > :first-child {
  position: relative;
  z-index: 2;

  font-family: var(--ot-font);
  font-weight: 600;
  font-size: 1.35em;
  line-height: 1;
  letter-spacing: 0.04em;
  color: #E4F1FF;
  text-shadow:
    0 0 10px rgba(168, 208, 255, 1),
    0 0 20px rgba(120, 190, 255, 0.75),
    0 1px 0 rgba(255, 255, 255, 0.2);
  text-align: center;
  white-space: nowrap;

  margin-top: -6px;
  margin-bottom: 10px;
}

/* 标签区 */
.wg-cd > :not(:first-child) {
  position: relative;
  z-index: 2;

  font-family: var(--ot-font);
  font-size: 0.68em;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0.14em;
  color: var(--ot-gold);
  text-shadow: 0 0 6px rgba(232, 200, 122, 0.7);
  text-align: center;
  white-space: nowrap;
}

/* ===== 台词：闪现 0.5 秒 + 渐渐消失 ===== */

/* 5 个伪元素共用样式 */
.wg-cd::after,
.wg-cd > :first-child::before,
.wg-cd > :first-child::after,
.wg-cd > :last-child::before,
.wg-cd > :last-child::after {
  position: absolute;
  left: calc(100% + 14px);
  top: 50%;
  transform: translateY(-50%);

  background: none;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  color: #FFFFFF;
  font-family: var(--ot-font);
  font-size: 0.78em;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: 0.06em;
  text-align: left;
  white-space: nowrap;

  text-shadow:
    0 0 6px var(--ot-dlg-glow),
    0 0 12px var(--ot-dlg-glow-2),
    0 0 20px var(--ot-dlg-glow-3),
    0 0 34px var(--ot-dlg-glow-4),
    0 0 48px rgba(91, 141, 217, 0.28);

  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  z-index: 20;

  animation: ot-line-fade 15s linear infinite;
}

/* 5 句台词 + 各自延迟 */
.wg-cd::after {
  content: "「今天也……一直在等你。」";
  animation-delay: 0s;
}
.wg-cd > :first-child::before {
  content: "「别走太远，我会担心的。」";
  animation-delay: 3s;
}
.wg-cd > :first-child::after {
  content: "「只要是你的事，我都记得。」";
  animation-delay: 6s;
}
.wg-cd > :last-child::before {
  content: "「过来，让我看看你。」";
  animation-delay: 9s;
}
.wg-cd > :last-child::after {
  content: "「有我在，什么都不用怕。」";
  animation-delay: 12s;
}

/* 悬停 / 按下 / 聚焦时打开可见性（哪句亮由动画控制） */
.wg-cd:hover::after,
.wg-cd:hover > :first-child::before,
.wg-cd:hover > :first-child::after,
.wg-cd:hover > :last-child::before,
.wg-cd:hover > :last-child::after,
.wg-cd:active::after,
.wg-cd:active > :first-child::before,
.wg-cd:active > :first-child::after,
.wg-cd:active > :last-child::before,
.wg-cd:active > :last-child::after,
.wg-cd:focus::after,
.wg-cd:focus > :first-child::before,
.wg-cd:focus > :first-child::after,
.wg-cd:focus > :last-child::before,
.wg-cd:focus > :last-child::after,
.wg-cd:focus-within::after,
.wg-cd:focus-within > :first-child::before,
.wg-cd:focus-within > :first-child::after,
.wg-cd:focus-within > :last-child::before,
.wg-cd:focus-within > :last-child::after {
  visibility: visible;
}

/* 每句：前 0.5 秒完全可见 → 之后渐渐淡出 → 剩下时间保持隐藏
   周期 15s，每句 3s
   0.5s / 15s ≈ 3.33%（完全可见的终点）
   3s / 15s = 20%（完全消失的终点） */
@keyframes ot-line-fade {
  0%     { opacity: 1; }
  3.33%  { opacity: 1; }
  20%    { opacity: 0; }
  100%   { opacity: 0; }
}

/* ========== E. 底栏 / Dock ========== */
.nav-dock {}

.foot {
  background: var(--dress-desk-glass-strong);
  border: 1px solid var(--ot-line);
  border-radius: 12px;
  padding: var(--stu-dock-pad) calc(var(--stu-dock-pad) + 4px);
  gap: var(--stu-dock-gap);
  box-shadow:
    var(--px) var(--px) 0 0 rgba(91, 141, 217, 0.18),
    0 0 24px rgba(168, 208, 255, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(22px) saturate(1.3);
  -webkit-backdrop-filter: blur(22px) saturate(1.3);
}

.foot.dock-mist {
  background: rgba(248, 251, 255, 0.55);
  box-shadow:
    var(--px) var(--px) 0 0 rgba(91, 141, 217, 0.12),
    0 0 18px rgba(168, 208, 255, 0.35);
}
html[data-theme="dark"] .foot.dock-mist {
  background: rgba(13, 24, 48, 0.55);
}

.foot.dock-slate {
  background: linear-gradient(180deg,
    rgba(58, 95, 168, 0.92) 0%,
    rgba(35, 58, 107, 0.95) 100%);
  border-color: var(--ot-gold-line);
  box-shadow:
    var(--px) var(--px) 0 0 rgba(35, 58, 107, 0.4),
    0 0 24px rgba(91, 141, 217, 0.45);
}

.foot.dock-drift {
  background: linear-gradient(180deg,
    var(--dress-desk-glass-strong) 0%,
    transparent 100%);
  border: none;
  box-shadow: none;
}

.dock-app-ico {
  width: var(--stu-dock-ico);
  height: var(--stu-dock-ico);
  border-radius: 6px;
  border: 1px solid var(--ot-line);
  background: linear-gradient(
    155deg,
    rgba(255, 255, 255, 0.72) 0%,
    rgba(220, 236, 255, 0.48) 50%,
    rgba(168, 208, 255, 0.35) 100%
  );
  box-shadow:
    3px 3px 0 0 rgba(91, 141, 217, 0.18),
    0 0 12px rgba(168, 208, 255, 0.4),
    inset 0 0 0 1px rgba(255, 255, 255, 0.55);
  transition: transform 0.1s steps(2, end), box-shadow 0.1s steps(2, end);
}
.dock-app-ico:active {
  transform: translate(2px, 2px);
  box-shadow:
    1px 1px 0 0 rgba(91, 141, 217, 0.15),
    0 0 8px rgba(168, 208, 255, 0.4);
}

.dock-app-empty {
  width: var(--stu-dock-ico);
  height: var(--stu-dock-ico);
  border: 1px dashed var(--ot-line);
  background: transparent;
  border-radius: 6px;
}

/* ========== F. 抽屉 / 选择器 ========== */
.picker {
  background: var(--dress-desk-glass-strong);
  border: 1px solid var(--ot-line);
  border-radius: 10px;
  box-shadow:
    6px 6px 0 0 rgba(91, 141, 217, 0.2),
    0 0 30px rgba(168, 208, 255, 0.5),
    inset 0 0 0 1px rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(22px) saturate(1.3);
  -webkit-backdrop-filter: blur(22px) saturate(1.3);
  color: var(--ot-night);
  font-family: var(--ot-font);
  padding: 14px 16px;
}

