/* —— G3. 顶部像素缎带 —— */
.status::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  pointer-events: none;
  z-index: 3;
  background: repeating-linear-gradient(90deg,
    var(--ot-gold) 0 8px,
    var(--ot-gold-hi) 8px 16px);
  opacity: 0.85;
  box-shadow: 0 1px 8px rgba(232, 200, 122, 0.5);
}

/* —— G4. 星群闪烁 —— */
.status::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background-image:
    radial-gradient(2px 2px at 10% 14%, rgba(255, 255, 255, 0.95) 50%, transparent 51%),
    radial-gradient(3px 3px at 26% 7%, rgba(232, 200, 122, 0.85) 50%, transparent 51%),
