    radial-gradient(3px 3px at 66% 86%, rgba(255, 255, 255, 0.9) 50%, transparent 51%),
    radial-gradient(2px 2px at 86% 92%, rgba(168, 208, 255, 0.85) 50%, transparent 51%);
