@keyframes ot-bubble-drift {
  0%   { transform: translateY(40px);  opacity: 0.35; }
  22%  { transform: translateY(-60px); opacity: 0.85; }
  50%  { transform: translateY(-220px); opacity: 1; }
  78%  { transform: translateY(-80px); opacity: 0.75; }
  100% { transform: translateY(40px);  opacity: 0.35; }
}

@keyframes ot-ribbon-sway {
  0%, 100% { transform: translateY(0) rotate(-2deg); }
  50%      { transform: translateY(-6px) rotate(2deg); }
}

@keyframes ot-twinkle {
  0%   { opacity: 1; }
  16%  { opacity: 0.45; }
  30%  { opacity: 0.95; }
  46%  { opacity: 0.55; }
  62%  { opacity: 1; }
  76%  { opacity: 0.4; }
  90%  { opacity: 0.9; }
  100% { opacity: 1; }
}

/* ========== H. 壁纸全屏铺满 ========== */
.desk,
.wallpaper,
.desk-wallpaper,
.desk-bg,
.home-wallpaper,
[class*="wallpaper"],
[class*="wall-paper"] {
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 100% !important;
  min-width: 100% !important;
  max-width: none !important;
  height: 100% !important;
  min-height: 100% !important;
  min-height: 100vh !important;
  min-height: 100dvh !important;
  margin: 0 !important;
  padding: 0 !important;
  background-size: cover !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

[class*="wallpaper"] img,
.desk-bg img,
.home-wallpaper img {
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 100% !important;
  min-height: 100% !important;
  object-fit: cover !important;
  object-position: center center !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* ========== I. 减少动效偏好 ========== */
@media (prefers-reduced-motion: reduce) {
  .device::before,
  .device::after,
  .status::after,
  .wg-cd::after,
  .wg-cd > :first-child::before,
  .wg-cd > :first-child::after,
  .wg-cd > :last-child::before,
  .wg-cd > :last-child::after {
    animation: none !important;
  }
  .app-box .ico,
  .dock-app-ico {
    transition: none !important;
  }
}
